const ADMIN_HTML="<!DOCTYPE html><html lang=\"es\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Admin \u2014 C5</title><style>\n*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,sans-serif;background:#0a0f1e;color:#e2e8f0;min-height:100vh;padding:20px}\n.wrap{max-width:640px;margin:0 auto}.logo{font-size:34px;font-weight:900;background:linear-gradient(135deg,#00ffcc,#00aaff);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:4px}\n.sub{color:#94a3b8;font-size:13px;margin-bottom:20px}\n.card{background:#111827;border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:18px;margin-bottom:14px}\ninput,select{width:100%;background:#1a2235;border:1px solid #1f2d45;border-radius:10px;padding:12px 14px;color:#e2e8f0;font-size:14px;outline:none;font-family:inherit}\n.btn{width:100%;padding:12px;border-radius:10px;border:none;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;margin-top:10px}\n.btn-p{background:linear-gradient(135deg,#00ffcc,#00b894);color:#001a14}\n.btn-ok{background:rgba(0,212,170,.15);border:1px solid rgba(0,212,170,.35);color:#00d4aa}\n.btn-no{background:rgba(255,77,109,.12);border:1px solid rgba(255,77,109,.3);color:#ff4d6d}\n.btn-doc{background:rgba(0,153,255,.12);border:1px solid rgba(0,153,255,.3);color:#00aaff}\n.tag{display:inline-block;background:rgba(255,179,71,.12);border:1px solid rgba(255,179,71,.3);color:#ffb347;border-radius:20px;padding:2px 10px;font-size:11px;font-weight:600}\n.meta{color:#94a3b8;font-size:12px;margin-top:4px;line-height:1.7}\n.empty{text-align:center;color:#94a3b8;padding:30px}\n.row{display:flex;gap:8px}.row .btn{flex:1}\n.msg{text-align:center;color:#94a3b8;font-size:13px;padding:10px}\n</style></head><body><div class=\"wrap\">\n<div class=\"logo\">C5 Admin</div>\n<div class=\"sub\">Panel de verificaciones \u2014 Levatech</div>\n<div class=\"card\" id=\"login-card\">\n<div style=\"font-size:13px;color:#94a3b8;margin-bottom:10px;\">Ingresa la clave de administrador</div>\n<input type=\"password\" id=\"admin-key\" placeholder=\"Clave secreta\" autocomplete=\"off\"/>\n<button class=\"btn btn-p\" onclick=\"cargar()\">Entrar</button>\n<div class=\"msg\" id=\"login-msg\"></div>\n</div>\n<div id=\"lista\"></div>\n</div>\n<script>\nvar KEY = null;\nfunction fmt(d){ try { return new Date(d).toLocaleString('es-CO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); } catch(e){ return d; } }\nvar TIPO = { rut:'RUT', camara:'Camara de Comercio', cedula:'Cedula de ciudadania' };\nasync function cargar() {\n  var k = document.getElementById('admin-key').value.trim();\n  if (!k) { document.getElementById('login-msg').textContent = 'Ingresa la clave'; return; }\n  document.getElementById('login-msg').textContent = 'Cargando...';\n  try {\n    var r = await fetch('/functions/admin-list', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ key: k }) });\n    var d = await r.json();\n    if (!r.ok) { document.getElementById('login-msg').textContent = d.error || 'Error'; return; }\n    KEY = k;\n    document.getElementById('login-card').style.display = 'none';\n    render(d.vers || [], d.cuentas || []);\n  } catch(e) { document.getElementById('login-msg').textContent = 'Error: ' + e.message; }\n}\nfunction render(vers, cuentas) {\n  var cMap = {}; cuentas.forEach(function(c){ cMap[c.id] = c; });\n  var el = document.getElementById('lista');\n  if (!vers.length) { el.innerHTML = '<div class=\"card empty\">No hay verificaciones pendientes \\u2705<br><br><button class=\"btn btn-doc\" onclick=\"cargar()\">Actualizar</button></div>'; return; }\n  var html = '<div class=\"msg\">' + vers.length + ' verificacion(es) pendiente(s) &middot; <a href=\"#\" onclick=\"cargar();return false;\" style=\"color:#00aaff;\">Actualizar</a></div>';\n  vers.forEach(function(v) {\n    var c = cMap[v.cuenta_id] || {};\n    html += '<div class=\"card\" id=\"card-' + v.id + '\">'\n      + '<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;\">'\n      + '<strong style=\"font-size:15px;\">' + (c.Nombre_Empresa || 'Cuenta #' + v.cuenta_id) + '</strong>'\n      + '<span class=\"tag\">\\u23f3 Pendiente</span></div>'\n      + '<div class=\"meta\">Documento: ' + (c.Nro_documento || '-') + ' &middot; Tipo cuenta: ' + (c.tipo_cuenta || '-') + '<br>'\n      + 'Adjunto: ' + (TIPO[v.tipo_documento] || v.tipo_documento || '-') + ' &middot; Enviado: ' + fmt(v.created_at) + '</div>'\n      + '<button class=\"btn btn-doc\" onclick=\"verDoc(' + JSON.stringify(String(v.archivo_path||'')).replace(/\"/g,'&quot;') + ')\">\\ud83d\\udcc4 Ver documento</button>'\n      + '<div class=\"row\">'\n      + '<button class=\"btn btn-ok\" onclick=\"decidir(' + v.id + ',' + v.cuenta_id + ',\\'aprobar\\',this)\">\\u2705 Aprobar</button>'\n      + '<button class=\"btn btn-no\" onclick=\"rechazar(' + v.id + ',' + v.cuenta_id + ',this)\">\\u274c Rechazar</button>'\n      + '</div></div>';\n  });\n  el.innerHTML = html;\n}\nasync function verDoc(path) {\n  if (!path) { alert('Sin archivo adjunto'); return; }\n  try {\n    var r = await fetch('/functions/admin-doc', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ key: KEY, path: path }) });\n    var d = await r.json();\n    if (d.url) window.open(d.url, '_blank');\n    else alert(d.error || 'No se pudo generar el enlace');\n  } catch(e) { alert('Error: ' + e.message); }\n}\nfunction rechazar(vid, cid, btn) {\n  var motivo = prompt('Motivo del rechazo (se enviara al usuario):');\n  if (!motivo || !motivo.trim()) return;\n  decidir(vid, cid, 'rechazar', btn, motivo.trim());\n}\nasync function decidir(vid, cid, decision, btn, motivo) {\n  btn.disabled = true; btn.textContent = 'Procesando...';\n  try {\n    var r = await fetch('/functions/admin-decidir', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ key: KEY, verif_id: vid, cuenta_id: cid, decision: decision, motivo: motivo || null }) });\n    var d = await r.json();\n    if (!r.ok || d.error) { alert(d.error || 'Error'); btn.disabled = false; return; }\n    var card = document.getElementById('card-' + vid);\n    if (card) card.innerHTML = '<div class=\"empty\">' + (decision === 'aprobar' ? '\\u2705 Aprobada y notificada' : '\\u274c Rechazada') + '</div>';\n  } catch(e) { alert('Error: ' + e.message); btn.disabled = false; }\n}\ndocument.getElementById('admin-key').addEventListener('keydown', function(e){ if (e.key === 'Enter') cargar(); });\n</script></body></html>";
const M=new Map();function rl(k,l,w){const n=Date.now(),r=M.get(k)||{c:0,s:n};if(n-r.s>w){r.c=1;r.s=n;}else r.c++;M.set(k,r);return r.c<=l;}
function ip(r){return r.headers.get("CF-Connecting-IP")||r.headers.get("X-Forwarded-For")||"x";}
function h(){return{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"POST,GET,OPTIONS","Access-Control-Allow-Headers":"Content-Type","Content-Type":"application/json"};}
function ok(r){const o=r.headers.get("Origin")||"",f=r.headers.get("Referer")||"";return o.includes("plataformac5.com")||o.includes("workers.dev")||f.includes("plataformac5.com")||f.includes("workers.dev");}
export default{
async fetch(q,e){

const u=new URL(q.url),p=u.pathname,i=ip(q);
if(p==="/"||p==="/index.html")return new Response(HTML,{headers:{"Content-Type":"text/html;charset=UTF-8"}});
if(p==="/autorizar")return new Response(AD,{headers:{"Content-Type":"text/html;charset=UTF-8"}});
if(p==="/autorizar-consulta")return new Response(AC,{headers:{"Content-Type":"text/html;charset=UTF-8"}});
if(p==="/admin")return new Response(ADMIN_HTML,{headers:{"Content-Type":"text/html;charset=UTF-8"}});
if(q.method==="OPTIONS")return new Response(null,{headers:h()});
if(!p.startsWith("/functions/")||q.method!=="POST")return new Response("Not found",{status:404});
if(!ok(q))return new Response(JSON.stringify({error:"No autorizado"}),{status:403,headers:h()});
if(!rl(i+"g",30,60000))return new Response(JSON.stringify({error:"Limite."}),{status:429,headers:h()});
if(p==="/functions/enviar-sms"){
if(!rl(i+"s",5,3600000))return new Response(JSON.stringify({ok:false}),{status:429,headers:h()});
try{const{celular,mensaje}=await q.json();const n="57"+celular.replace(/\D/g,"").slice(-10);const r=await fetch("https://"+e.INFOBIP_BASE_URL+"/sms/2/text/advanced",{method:"POST",headers:{"Authorization":"App "+e.INFOBIP_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({messages:[{from:"PlataformaC5",destinations:[{to:n}],text:mensaje}]})});const d=await r.json();const s=d.messages&&d.messages[0]?d.messages[0].status.name:"X";return new Response(JSON.stringify({ok:s==="MESSAGE_ACCEPTED"||s==="PENDING_ACCEPTED",status:s}),{headers:h()});}catch(ex){return new Response(JSON.stringify({ok:false,error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/enviar-email"){
if(!rl(i+"em",10,3600000))return new Response(JSON.stringify({ok:false}),{status:429,headers:h()});
try{const{to,subject,html:htmlBody}=await q.json();if(!to||!subject||!htmlBody)throw new Error("Datos incompletos");const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+e.RESEND_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({from:"Plataforma C5 <notificaciones@plataformac5.com>",to:[to],subject,html:htmlBody})});const d=await r.json();return new Response(JSON.stringify(r.ok?{ok:true,id:d.id}:{ok:false,error:d.message}),{headers:h()});}catch(ex){return new Response(JSON.stringify({ok:false,error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/crear-pago"){
try{const{plan,valor,empresa_id,empresa_nombre,celular}=await q.json();const rf="C5-"+plan.toUpperCase()+"-"+empresa_id+"-"+Date.now();const r=await fetch("https://integrations-api.bold.co/online/link/v1",{method:"POST",headers:{"Authorization":"x-api-key "+e.BOLD_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({amount_type:"CLOSE",amount:{currency:"COP",total_amount:valor},description:"C5 "+plan,reference_id:rf,customer:{name:empresa_nombre,phone:"57"+celular}})});const d=await r.json();return new Response(JSON.stringify(r.ok?{url:d.payload.url,referencia:rf}:{error:"Error"}),{headers:h()});}catch(ex){return new Response(JSON.stringify({error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/admin-list"){
if(!rl(i+"al",20,3600000))return new Response(JSON.stringify({error:"Limite."}),{status:429,headers:h()});
try{
const{key}=await q.json();
if(!e.ADMIN_KEY||key!==e.ADMIN_KEY)return new Response(JSON.stringify({error:"Clave incorrecta"}),{status:403,headers:h()});
const r=await fetch(e.SUPABASE_URL+"/rest/v1/Tbl_Verificaciones?estado=eq.pendiente&select=*&order=created_at.asc",{headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY}});
const vers=await r.json();
let cuentas=[];
const ids=[...new Set((Array.isArray(vers)?vers:[]).map(v=>v.cuenta_id).filter(Boolean))];
if(ids.length){
const rc=await fetch(e.SUPABASE_URL+"/rest/v1/Tbl_Cuenta?id=in.("+ids.join(",")+")&select=id,Nombre_Empresa,Nro_documento,tipo_cuenta,email_contacto",{headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY}});
cuentas=await rc.json();
}
return new Response(JSON.stringify({vers:Array.isArray(vers)?vers:[],cuentas:Array.isArray(cuentas)?cuentas:[]}),{headers:h()});
}catch(ex){return new Response(JSON.stringify({error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/admin-doc"){
try{
const{key,path}=await q.json();
if(!e.ADMIN_KEY||key!==e.ADMIN_KEY)return new Response(JSON.stringify({error:"Clave incorrecta"}),{status:403,headers:h()});
if(!path||/[^a-zA-Z0-9._-]/.test(path))return new Response(JSON.stringify({error:"Ruta invalida"}),{status:400,headers:h()});
const r=await fetch(e.SUPABASE_URL+"/storage/v1/object/sign/verificaciones/"+path,{method:"POST",headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY,"Content-Type":"application/json"},body:JSON.stringify({expiresIn:600})});
const d=await r.json();
if(!r.ok||!d.signedURL)return new Response(JSON.stringify({error:d.message||"No se pudo firmar"}),{status:500,headers:h()});
return new Response(JSON.stringify({url:e.SUPABASE_URL+"/storage/v1"+d.signedURL}),{headers:h()});
}catch(ex){return new Response(JSON.stringify({error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/admin-decidir"){
try{
const{key,verif_id,cuenta_id,decision,motivo}=await q.json();
if(!e.ADMIN_KEY||key!==e.ADMIN_KEY)return new Response(JSON.stringify({error:"Clave incorrecta"}),{status:403,headers:h()});
if(!verif_id||!cuenta_id||!["aprobar","rechazar"].includes(decision))return new Response(JSON.stringify({error:"Datos invalidos"}),{status:400,headers:h()});
const hs={"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY,"Content-Type":"application/json","Prefer":"return=minimal"};
await fetch(e.SUPABASE_URL+"/rest/v1/Tbl_Verificaciones?id=eq."+parseInt(verif_id),{method:"PATCH",headers:hs,body:JSON.stringify({estado:decision==="aprobar"?"aprobada":"rechazada",motivo_rechazo:motivo||null,revisado_at:new Date().toISOString()})});
await fetch(e.SUPABASE_URL+"/rest/v1/Tbl_Cuenta?id=eq."+parseInt(cuenta_id),{method:"PATCH",headers:hs,body:JSON.stringify({verificacion_estado:decision==="aprobar"?"verificado":"rechazada"})});
const rc=await fetch(e.SUPABASE_URL+"/rest/v1/Tbl_Cuenta?id=eq."+parseInt(cuenta_id)+"&select=email_contacto,Nombre_Empresa",{headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY}});
const cs=await rc.json();
const cu=cs&&cs[0];
if(cu&&cu.email_contacto){
const badgeImg='<span style="display:inline-block;background:#00aaff;color:#fff;border-radius:50%;width:20px;height:20px;text-align:center;line-height:20px;font-size:13px;font-weight:700;vertical-align:middle;">&#10003;</span>';
const htmlOk='<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;"><h2 style="color:#00ffcc;">Plataforma C5</h2><p style="font-size:16px;line-height:1.7;">&iexcl;Felicitaciones <strong>'+(cu.Nombre_Empresa||"")+'</strong>! '+badgeImg+'</p><p style="color:#94a3b8;line-height:1.7;">Tu cuenta fue <strong style="color:#00aaff;">verificada</strong>. Desde ahora tu insignia azul aparece en tu perfil, en las consultas y en las notificaciones que envias, dando mas confianza a tus clientes.</p><a href="https://plataformac5.com" style="display:inline-block;background:linear-gradient(135deg,#00ffcc,#00b894);color:#001a14;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600;margin-top:12px;">Ir a mi cuenta</a></div>';
const htmlNo='<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;"><h2 style="color:#00ffcc;">Plataforma C5</h2><p style="font-size:15px;line-height:1.7;">Hola <strong>'+(cu.Nombre_Empresa||"")+'</strong>, revisamos tu solicitud de verificacion y no pudo ser aprobada.</p><p style="color:#94a3b8;line-height:1.7;">Motivo: '+(motivo||"documento no valido")+'</p><p style="color:#94a3b8;line-height:1.7;">Puedes enviar una nueva solicitud desde tu perfil con un documento valido.</p></div>';
await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+e.RESEND_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({from:"Plataforma C5 <notificaciones@plataformac5.com>",to:[cu.email_contacto],subject:decision==="aprobar"?"\u2705 Tu cuenta fue verificada \u2014 Plataforma C5":"Resultado de tu verificacion \u2014 Plataforma C5",html:decision==="aprobar"?htmlOk:htmlNo})});
}
return new Response(JSON.stringify({ok:true}),{headers:h()});
}catch(ex){return new Response(JSON.stringify({error:ex.message}),{status:500,headers:h()});}
}
if(p==="/functions/cambiar-contrasena"){
if(!rl(i+"p",5,3600000))return new Response(JSON.stringify({error:"Limite."}),{status:429,headers:h()});
try{const{documento,password}=await q.json();const em=documento+"@plataformac5.com";const ru=await fetch(e.SUPABASE_URL+"/auth/v1/admin/users?email="+encodeURIComponent(em),{headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY}});const ud=await ru.json();const usr=ud.users&&ud.users[0];if(!usr)return new Response(JSON.stringify({error:"No encontrado"}),{status:404,headers:h()});const r=await fetch(e.SUPABASE_URL+"/auth/v1/admin/users/"+usr.id,{method:"PUT",headers:{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY,"Content-Type":"application/json"},body:JSON.stringify({password})});const d=await r.json();return new Response(JSON.stringify(r.ok?{ok:true}:{error:d.message}),{headers:h()});}catch(ex){return new Response(JSON.stringify({error:ex.message}),{status:500,headers:h()});}
}
return new Response("Not found",{status:404});

},
async scheduled(event, env, ctx) {
ctx.waitUntil(ejecutarNotificacionesProgramadas(env));
}
};


// â”€â”€ CRON JOB â€” NOTIFICACIONES PROGRAMADAS â”€â”€
async function ejecutarNotificacionesProgramadas(env) {
const S = env.SUPABASE_URL;
const K = env.SUPABASE_SERVICE_KEY;
const hoy = new Date().toISOString().slice(0,10);
const r = await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?estado=eq.pendiente&fecha_programada=lte.'+hoy+'&select=*',{
headers:{'apikey':K,'Authorization':'Bearer '+K}
});
const notifs = await r.json();
if (!Array.isArray(notifs) || notifs.length === 0) return;
for (const n of notifs) {
const dr = await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+n.deuda_id+'&select=estado,celular_deudor,email_deudor,Valor_total_deuda,nombre_empresa',{
headers:{'apikey':K,'Authorization':'Bearer '+K}
});
const deudas = await dr.json();
const deuda = deudas && deudas[0];
if (!deuda || deuda.estado === 'eliminada') {
await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?id=eq.'+n.id,{
method:'PATCH',headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':'return=minimal'},
body:JSON.stringify({estado:'cancelada'})
});
continue;
}
const valor = '$'+parseFloat(deuda.Valor_total_deuda).toLocaleString('es-CO',{maximumFractionDigits:0});
const empresa = deuda.nombre_empresa || 'el negocio';
let msg = '';
if (n.tipo === 'vencimiento') msg = 'Plataforma C5: Tu obligacion de '+valor+' con '+empresa+' vence hoy. Contactalos para evitar mora.';
else if (n.tipo === 'preaviso') msg = 'Plataforma C5: AVISO. Tu obligacion de '+valor+' con '+empresa+' sera reportada en mora pronto. Contactalos ya.';
else msg = 'Plataforma C5: Recordatorio. Tu obligacion de '+valor+' con '+empresa+' vence en '+n.dias_antes+' dias.';
let enviado = false;
if (deuda.email_deudor) {
const asunto = n.tipo === 'preaviso' ? 'âš ï¸ Aviso de mora â€” C5' : 'ðŸ”” Recordatorio de obligaciÃ³n â€” C5';
const htmlBody = '<div style="font-family:Arial,sans-serif;max-width:520px;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;">'
+'<h2 style="color:#00ffcc;">Plataforma C5</h2>'
+'<p style="font-size:15px;line-height:1.7;">'+msg+'</p>'
+'<a href="https://plataformac5.com" style="display:inline-block;background:linear-gradient(135deg,#00ffcc,#00b894);color:#001a14;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600;margin-top:16px;">Ver mis obligaciones</a>'
+'</div>';
const er = await fetch('https://api.resend.com/emails',{
method:'POST',headers:{'Authorization':'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json'},
body:JSON.stringify({from:'Plataforma C5 <notificaciones@plataformac5.com>',to:[deuda.email_deudor],subject:asunto,html:htmlBody})
});
enviado = er.ok;
}
if (!enviado && deuda.celular_deudor) {
const n2 = '57'+deuda.celular_deudor.replace(/\D/g,'').slice(-10);
await fetch('https://'+env.INFOBIP_BASE_URL+'/sms/2/text/advanced',{
method:'POST',headers:{'Authorization':'App '+env.INFOBIP_API_KEY,'Content-Type':'application/json'},
body:JSON.stringify({messages:[{from:'PlataformaC5',destinations:[{to:n2}],text:msg}]})
});
enviado = true;
}
await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?id=eq.'+n.id,{
method:'PATCH',headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':'return=minimal'},
body:JSON.stringify({estado: enviado ? 'enviada' : 'fallida', fecha_enviada: new Date().toISOString(), mensaje_enviado: msg})
});
}
}
  
